import{_ as r,l,o as e,c as i,v as t,p as s,x as o,d,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"报价惯例","description":"","frontmatter":{"title":"报价惯例","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/quoting-conventions.md","filePath":"quant/quoting-conventions.md","lastUpdated":1789023840000}'),E={name:"quant/quoting-conventions.md"};function c(h,a,m,u,T,B){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="报价惯例" tabindex="-1">报价惯例 <a class="header-anchor" href="#报价惯例" aria-label="Permalink to &quot;报价惯例&quot;">​</a></h1><div class="epigraph"><p>同一张曲面，股权按执行价或 Delta 报隐波，外汇按 ATM、风险反转与蝶式报；弄错惯例，校准的是另一个市场。</p><footer>—— FX 惯例见 Clark, Foreign Exchange Option Pricing；股权惯例对照 Natenberg 与交易所规则</footer></div><p><a href="/quant/calibration-global-opt">上一课</a>把随机波动校准写成非凸：RMSE 接近的谷可以对冲比完全不同，多起点只做粗定位。缺口是校准课默认输入已经是「隐波网格」——网格从哪来。本课把报价惯例钉成坐标：ATM、Delta、年化日历。不重讲差分进化。后课 XVA 与 FX 课序默认已经读完：惯例不是模型，用错 25Δ 会让执行价偏一截。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股权指数期权通常报价格或报 Black 隐波，执行价是点数，\\(T\\) 用交易日或日历日因交易所而异。外汇 OTC 报 ATM 波动、25Δ 风险反转、25Δ 蝶式，Delta 还分 pips 与 premium-adjusted、spot 与 forward。把 FX 的 25Δ 当成股权的 25Δ 去取 \\(K\\)，执行价能偏一截，校准全部错位。问题是在解析层写清：惯例是<strong>坐标变换</strong>，不是模型。</p><p>利率期权还有 lognormal vs normal（bp vol）、年化 365/360、是否用终端互换 Delta。后课负利率会强制 normal/shifted；本课只要求：引擎入口处把所有报价映到内部的 \\((T,K,\\sigma)\\) 或 \\((T,\\Delta,\\sigma)\\)，并保存原惯例以便对冲单能改回市场语言。</p><h3 id="atm-有不止一种" tabindex="-1">ATM 有不止一种 <a class="header-anchor" href="#atm-有不止一种" aria-label="Permalink to &quot;ATM 有不止一种&quot;">​</a></h3><p>ATM spot、ATM forward、ATM Delta-neutral（使跨式 Delta 抵消）在有偏斜与利率时不是同一 \\(K\\)。FX 默认常是 Delta-neutral ATM。用错 ATM，RR 与 BF 的分解会把水平成分漏进倾斜。Clark 把这些定义写成公式，实现应以一本惯例手册为准，而不是以交易员口头「ATM 就是平值」。</p><p><span class="marginnote">Premium-adjusted Delta 在高波动、长期限外汇里把 \\(K\\) 往价外推。新兴市场期权忽略这一项，对冲比会系统性偏。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>内部规范：到期用 year-fraction 的明确日计数；执行价用绝对 \\(K\\)；波动用 Black 或 normal 的标签。每个市场写一个 adapter：报价 → 内部，希腊值 → 报价（对 RR/BF 的 Jacobian）。测试：把标准报价换成曲面再换回，应回到价差以内。日历：交易日 vs 营业日、fixing 假期，影响亚式与障碍观察，不只影响 \\(T\\)。</p><p>对冲单必须用对手的惯例下单：FX 用 RR/BF 结构，不要下三个独立的「25Δ 看涨」。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>惯例把同一测度下的价格编码成市场喜欢交易的正交组合（水平、倾斜、凸性）。RR/BF 近似 PCA 的第二、第三成分，这就是为什么 FX 校准直接在 ATM/RR/BF 上做更稳。股权若按每个 \\(K\\) 报，正交化要在内部做。弄错惯例等于在错误的主成分上校准，正则化也救不了。</p>',14)),(e(),s(A,null,{default:o(()=>[p(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20FX%5B%22FX%20ATM%20RR%20BF%22%5D%20--%3E%20Adp%5B%22%E6%83%AF%E4%BE%8B%E9%80%82%E9%85%8D%E5%99%A8%22%5D%0A%20%20Eq%5B%22%E8%82%A1%E6%9D%83%20K%20%E6%88%96%20Delta%20%E9%9A%90%E6%B3%A2%22%5D%20--%3E%20Adp%0A%20%20IR%5B%22%E5%88%A9%E7%8E%87%20bp%20vol%20%E6%88%96%20lognormal%22%5D%20--%3E%20Adp%0A%20%20Adp%20--%3E%20Int%5B%22%E5%86%85%E9%83%A8%20T%20K%20%CF%83%22%5D%0A%20%20Int%20--%3E%20Cal%5B%22%E6%A0%A1%E5%87%86%E4%B8%8E%20AAD%20%E6%A1%B6%22%5D%0A%20%20Cal%20--%3E%20Back%5B%22%E5%B8%8C%E8%85%8A%E5%80%BC%E6%98%A0%E5%9B%9E%E5%B8%82%E5%9C%BA%E7%BB%93%E6%9E%84%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>交易所规则改 Delta 定义、节假日日历、合约乘数，都会让历史曲面不可比。自动化若缓存「昨天的 25Δ 对应的 \\(K\\)」，现货一跳 \\(K\\) 就过期。本课不展开各交易所附录；生产以现行确认书与 ISDA 定义为准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报价惯例是坐标，不是模型；ATM 与 Delta 定义必须写死。</li><li>内部用统一 \\((T,K)\\)，对冲用市场结构的 Jacobian 换回。</li><li>FX 的 RR/BF、利率的 bp vol、股权的 \\(K\\) 网格不可混用。</li><li>出处：Clark, <em>Foreign Exchange Option Pricing</em>；股权惯例见 Natenberg 与各交易所规则。</li></ul>',4))])}const f=r(E,[["render",c]]);export{D as __pageData,f as default};
